1	package com.example.starter.compliance.support;
2	
3	import com.example.starter.compliance.ApiException;
4	import com.fasterxml.jackson.core.JsonProcessingException;
5	import com.fasterxml.jackson.databind.DeserializationFeature;
6	import com.fasterxml.jackson.databind.JsonNode;
7	import com.fasterxml.jackson.databind.ObjectMapper;
8	import java.io.IOException;
9	import java.io.UncheckedIOException;
10	import java.math.BigDecimal;
11	import java.util.ArrayList;
12	import java.util.List;
13	import java.util.Map;
14	import java.util.TreeMap;
15	import org.springframework.http.HttpStatus;
16	
17	/**
18	 * 快照序列化与幂等指纹工具：
19	 * 快照以 JSON 落库，保证可复算、重复查询结果稳定；
20	 * 指纹规范化 BigDecimal 标度（1.0 与 1.00 视为同参）并递归按字段名排序。
21	 */
22	public final class JsonSupport {
23	
24	    private static final ObjectMapper MAPPER = new ObjectMapper()
25	            .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
26	
27	    private JsonSupport() {
28	    }
29	
30	    public static String write(Object value) {
31	        try {
32	            return MAPPER.writeValueAsString(value);
33	        } catch (JsonProcessingException e) {
34	            throw new UncheckedIOException(e);
35	        }
36	    }
37	
38	    public static <T> T read(String json, Class<T> type) {
39	        try {
40	            return MAPPER.readValue(json, type);
41	        } catch (IOException e) {
42	            throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR, "SNAPSHOT_UNREADABLE",
43	                    "存储快照无法解析");
44	        }
45	    }
46	
47	    public static <T> T convert(Object value, Class<T> type) {
48	        return MAPPER.convertValue(value, type);
49	    }
50	
51	    public static JsonNode readTree(String json) {
52	        try {
53	            return MAPPER.readTree(json);
54	        } catch (IOException e) {
55	            throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR, "SNAPSHOT_UNREADABLE",
56	                    "存储快照无法解析");
57	        }
58	    }
59	
60	    /**
61	     * 反序列化幂等重放响应：存储体为首次结果（replayed=false），重放时将响应体 replayed 置为 true，
62	     * 其余字段与首次结果完全一致。
63	     */
64	    public static <T> T readReplayed(String json, Class<T> type) {
65	        JsonNode node = readTree(json);
66	        if (node.isObject() && node.has("replayed")) {
67	            ((com.fasterxml.jackson.databind.node.ObjectNode) node).put("replayed", true);
68	        }
69	        return MAPPER.convertValue(node, type);
70	    }
71	
72	    /**
73	     * 规范化业务报文：BigDecimal 去尾随零（1.00 与 1.0 视为同参），对象键递归字典序排序，
74	     * 输出稳定 JSON 字符串作为 requestId 幂等指纹输入。
75	     */
76	    public static String canonical(Object value) {
77	        Object normalized = normalize(MAPPER.convertValue(value, JsonNode.class));
78	        try {
79	            return MAPPER.writeValueAsString(normalized);
80	        } catch (JsonProcessingException e) {
81	            throw new UncheckedIOException(e);
82	        }
83	    }
84	
85	    private static Object normalize(JsonNode node) {
86	        if (node == null || node.isNull()) {
87	            return null;
88	        }
89	        if (node.isObject()) {
90	            TreeMap<String, Object> sorted = new TreeMap<>();
91	            node.fields().forEachRemaining(entry ->
92	                    sorted.put(entry.getKey(), normalize(entry.getValue())));
93	            return sorted;
94	        }
95	        if (node.isArray()) {
96	            List<Object> list = new ArrayList<>(node.size());
97	            node.forEach(child -> list.add(normalize(child)));
98	            return list;
99	        }
100	        if (node.isNumber()) {
101	            return new BigDecimal(node.asText()).stripTrailingZeros().toPlainString();
102	        }
103	        if (node.isBoolean()) {
104	            return node.booleanValue();
105	        }
106	        return node.asText();
107	    }
108	}
