32	
33	        assertThat(first.replayed()).isFalse();
34	        assertThat(replay.replayed()).isTrue();
35	        // 同键同参返回首次结果：同一配方主键，不产生重复配方。
36	        assertThat(replay.body().formulaId()).isEqualTo(first.body().formulaId());
