        assertThat(o.success()).isTrue();
        assertThat(o.result().body().recordId()).isNotNull();
    });
    long firstId = outcomes.get(0).result().body().recordId();
    long secondId = outcomes.get(1).result().body().recordId();
    assertThat(firstId).isEqualTo(secondId);
    AtomicInteger replayed = new AtomicInteger();
    outcomes.forEach(o -> {
        if (o.result().replayed()) {
            replayed.incrementAndGet();
        }
    });
    assertThat(replayed.get()).isEqualTo(1);
    assertThat(gateService.findLineProductionRecords("LC5")).hasSize(1);
    assertThat(gateRepository.findProductionLine("LC5").orElseThrow().occupancyVersion())
            .isEqualTo(2);
}

